---@class BT.Composite
local Composite = Class("Composite", Behavior)
Composite.TaskStatus = Behavior.TaskStatus
Composite.AbortTypes = AbortTypes
Composite.BTUtils    = BTUtils

function Composite:__init()
    Behavior.__init(self)

    self.btType = Behavior.BehaviorTreeType.Composites
    
    self._abortType = AbortTypes.None
    
    self._children = {}
    
    self._hasLowerPriorityConditionalAbort = false
    
    self._currentChildIndex = 1
end

function Composite:__delete()

end

function Composite:Invalidate()
    Behavior.Invalidate(self)
    
    for i, child in ipairs(self._children) do
        child:Invalidate()
    end
    
end

function Composite:OnStart()
    ---较低优先级的中止发生在下一级，所以我们在这里检查是否有
    self._hasLowerPriorityConditionalAbort = self:HasLowerPriorityConditionalAbortInChildren()
    self._currentChildIndex = 1
end

function Composite:OnEnd()
    ---我们已经做好了使我们的子节点无效的准备，使他们再下一帧做好准备 
    for i, child in ipairs(self._children) do
        child:Invalidate()
    end
end

---HasLowerPriorityConditionalAbortInChildren
---检查复合体的子代，看是否有具有LowerPriority AbortType的复合体
function Composite:HasLowerPriorityConditionalAbortInChildren()
    for i, child in ipairs(self._children) do
        if child.abortType and BTUtils.HasAbortType(child.abortType, AbortTypes.LowerPriority) then
            --- 现在确保第一个子节点是一个条件性的
            if child:IsFirstChildConditional() then
                return true
            end
        end
    end
    
    return false
    
end

---IsFirstChildConditional
---如果一个复合体的第一个子节点是一个条件体，返回true。用来处理条件性中止
function Composite:IsFirstChildConditional()
    return BTUtils.IsConditional(self:GetFirstNode())
end

---AddChild
--- 为这个复合体添加一个子节点
---@param child BT.Composite
function Composite:AddChild(child)
    table.insert(self._children, child)
end

---UpdateSelfAbortConditional
---检查任何IConditional的子代，看它们是否已经改变了状态
---@param context table
---@param statusCheck BT.TaskStatus
function Composite:UpdateSelfAbortConditional(context, statusCheck)
    --- 检查任何IConditional的子任务，看它们是否改变了状态

    for i = 1, self._currentChildIndex do
        local child = self._children[i]
        if BTUtils.IsConditional(child) then
            local status = self:UpdateConditionalNode(context, child)
            if status ~= statusCheck then
                self._currentChildIndex = i
                --- 我们有一个中止，所以我们使子节点无效，所以他们被重新评估
                for _, node in ipairs(self._children) do
                    node:Invalidate()
                end
                
                break
            end
        end
    end
    
end

---updateLowerPriorityAbortConditional
---检查任何具有LowerPriority AbortType和Conditional作为第一个子代的组合体。
---如果它找到一个，它将执行条件，如果状态不等于 statusCheck，_currentChildIndex将被更新，即当前运行的Action将被中止。
---@param context table
---@param statusCheck BT.TaskStatus
function Composite:UpdateLowerPriorityAbortConditional(context, statusCheck)
    --- 检查任何较低优先级的任务，看它们是否改变了状态
    for i = 1, self._currentChildIndex do
        local composite = self._children[i]
        if composite.abortType and BTUtils.HasAbortType(composite.abortType, AbortTypes.LowerPriority) then
            --- 现在我们只得到条件的状态（更新而不是执行），看看它是否发生了变化，并对条件装饰器加以注意
            local firstNode = composite:GetFirstNode()
            local status    = self:UpdateConditionalNode(context, firstNode)
            if status ~= statusCheck then
                self._currentChildIndex = i
                --- 我们有一个中止，所以我们使子节点无效，所以他们被重新评估
                for _, node in ipairs(self._children) do
                    node:Invalidate()
                end

                break
            end
        end
    end
end

---UpdateConditionalNode
---帮助器，用于获取一个条件或一个条件装饰器的任务状态
---@param context table
---@param node BT.Composite
function Composite:UpdateConditionalNode(context, node)
    if node.executeConditional then
        node:executeConditional(context, true)
    else
        node:Update(context)
    end
end

function Composite:GetFirstNode()
    return self._children[1]
end

function Composite:IsFirstIndex()
    return self._currentChildIndex == 1
end

function Composite:ResetCurrentIndex()
    self._currentChildIndex = 1
end

return Composite
 